def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        bg = max(set(row), key=row.count)
        i = len(row) - 1
        while i >= 0 and row[i] == bg:
            i -= 1
        if 0 <= i < len(row) - 1:
            out[r][i + 1:] = [1] * (len(row) - i - 1)
    return out
